test("a fast actor reaches quorum without waiting for a slow peer and aborts its fabric wait", async () => {
  const territory = fixture(), ledgerRoot = join(territory, "trajectory-ledger");
  const calls = new Map(); let slowAborted = false;
  const dispatch = async (jobs, { signal } = {}) => {
    const job = jobs[0], actorId = Number(job.id.match(/:actor:(\d+):/)[1]);
    calls.set(actorId, (calls.get(actorId) || 0) + 1);
    if (actorId === 2) {
      return new Promise((resolve, reject) => {
        signal.addEventListener("abort", () => {
          slowAborted = true;
          const error = new Error("stopped after peer quorum"); error.name = "AbortError"; reject(error);
        }, { once: true });
      });
    }
    if (calls.get(actorId) === 1) return [response(job, { action: "read", args: { path: "calc.mjs" }, reason: "inspect the source first" })];
    return [response(job, {
      action: "edit",
      args: { path: "calc.mjs", blocks: { search: "export const add = (a, b) => a - b;\n", replace: "export const add = (a, b) => a + b;\n" } },
      reason: "repair the implementation after inspection",
    })];
  };
  const result = await runMission({
    id: "urn:test:mission:independent-actor-progression",
    objective: "Repair the add function without waiting for a slow peer.",
    territory,
