    maxRounds: 5,
    minVerifiedCandidates: 1,
    apply: false,
  }, { dispatch, ledgerRoot });

  assert.equal(result.outcome.verified, true);
  assert.equal(calls.get(1), 2);
  assert.equal(calls.get(2), 1);
  assert.equal(slowAborted, true);
  assert.equal(result.actors.find((actor) => actor.id === 2).status, "stopped");
});
